insert into public.campfire_days (series_id, season_number, week, day, data) values
('dark-moon', 1, 6, 1, '{"place":"The wall room (Six nights)","narrated":false,"tone":"wry","cupNight":false,"opener":"Quiet''s good in a hole in a wall. I''ll take it.","forkA":"They think the light was nothing.","forkB":"They know someone''s in the wall.","callback":"At dusk you crossed the wall and nobody heard. By the end of the night a watchman was looking straight at your window.","nudge":"{friend:Aim}, an arrow under the window, pointing down. What does it want us to find?","riddle":{"q":"What can fill a room and take no space?","a":"light","quip":"A little of it, please.","accept":["light"],"maxTries":3},"leads":[{"id":"6-1-1","place":"the slit, after dark","actions":[{"attr":"Aim","verb":"watch the lanterns from the slit"},{"attr":"Intellect","verb":"follow where each lantern goes"}],"clueTitle":"No light inside","clueText":"Not a candle burns in the room. Every lantern you can see from the slit is out in the square, and none of them reaches in.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"6-1-2","place":"the board in the square","actions":[{"attr":"Aim","verb":"watch the board from the slit at dusk"},{"attr":"Intellect","verb":"watch the man with the chalk, not the board"}],"clueTitle":"One look down the hill","clueText":"At dusk the watchman with the chalk stops before he strikes the board. He turns, looks down the hill at the wall, and then strikes it.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"6-1-3","place":"the stone niche where it lay","actions":[{"attr":"Craft","verb":"hold a hand inside and feel the stone"},{"attr":"Intellect","verb":"look at the niche with the lamp unlit"}],"clueTitle":"The old soot","clueText":"The back of the stone niche is blackened in one small round patch, the way a candle marks stone over years. The niche faces the inner wall, away from the slit.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"We let them go.\"* Why spare anyone, on a night like that?","weekQuestion":"What will the fifth do in his hall?","pull":"**The hall is sealed, and the Seekers left a way in, somewhere. The arrow points down: the defenders'' barracks, under the wall.**"}'::jsonb),
('dark-moon', 1, 6, 2, '{"place":"The barracks under the wall (Five nights)","narrated":false,"tone":"quiet","cupNight":false,"opener":"The dead move when nobody watches, and they passed you by. Sit down a minute.","forkA":"They go up to the hall to answer a call.","forkB":"They go up to guard it.","callback":"Last week you couldn''t be sure a helm had turned toward you. Today one stood in your doorway and looked at the fallen stone instead.","nudge":"{friend:Agility}, the dead passed us by on their way up. Called, or on guard?","riddle":{"q":"What can you hold but never see, and the more you hold it the less you speak?","a":"your breath","quip":"Hold yours.","accept":["breath","your breath"],"maxTries":3},"leads":[{"id":"6-2-1","place":"where the spears once stood","actions":[{"attr":"Craft","verb":"look at the dust under the racks"},{"attr":"Intellect","verb":"walk the racks end to end"}],"clueTitle":"The swept racks","clueText":"The spear-racks along the wall are empty, and the dust under every one is swept clean in the same short arc.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"6-2-2","place":"the stair up to the street","actions":[{"attr":"Agility","verb":"climb to the top step and listen"},{"attr":"Intellect","verb":"count what you hear"}],"clueTitle":"Every foot at once","clueText":"When the heartbeat comes, you hear iron move all over the city at once: one scrape of a foot from every street, then quiet.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"6-2-3","place":"the kitchen whose fire went out","actions":[{"attr":"Craft","verb":"look over the board and the pot"},{"attr":"Might","verb":"lift the lid of the cold pot"}],"clueTitle":"Bowls never filled","clueText":"In the kitchen, bowls are set out along the board for a meal, and a ladle lies in the cold pot. Not one bowl was filled.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"That is how we found the shards.\"* How could a mark help anyone find one?","weekQuestion":"What will the fifth do in his hall?","pull":"**They are not coming for you. They are going to him. And wherever the Seekers'' way in begins, it begins at his walls. The great square, after dark.**"}'::jsonb),
('dark-moon', 1, 6, 3, '{"place":"The great square (Four nights)","narrated":false,"tone":"wry","cupNight":false,"opener":"The hall''s warm from within. More faithful arriving. What''s missing is a door.","forkA":"There is no way in at the front.","forkB":"There is, and it isn''t ours.","callback":"The soldiers are three streets nearer the hall. Round the Order''s fire there are twice as many as before.","nudge":"{friend:Intellect}, where would the Seekers have left a door?","riddle":{"q":"What is warm in the cold but has no fire?","a":"a blanket","quip":"Bring one.","accept":["a blanket","blanket"],"maxTries":3},"leads":[{"id":"6-3-1","place":"the foot of the great doors","actions":[{"attr":"Agility","verb":"slip along the wall to the doors"},{"attr":"Craft","verb":"look at the ground under the seam"}],"clueTitle":"The unbroken drift","clueText":"At the foot of the great doors, dust has drifted against the seam in one smooth bank, from post to post. Nothing has crossed it.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"6-3-2","place":"the ruined house across from the hall","actions":[{"attr":"Aim","verb":"pick out what is stacked by their fire"},{"attr":"Agility","verb":"creep along the ruined house''s wall"}],"clueTitle":"Clean robes","clueText":"By the Order''s fire the new men''s packs are stacked in a row. On top of each lies a folded robe, brushed clean of the road.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"6-3-3","place":"the hall''s great wall","actions":[{"attr":"Craft","verb":"feel the stone, hand over hand"},{"attr":"Might","verb":"climb a little way and feel higher"}],"clueTitle":"Warm low down","clueText":"Move your palm up the wall and the stone cools. The warmth is only low down, at the height of your knee and below.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"None of us could bear to lift him.\"* What kept them from lifting him?","weekQuestion":"What will the fifth do in his hall?","pull":"**He is on the other side of this wall. Inside, on the night the moon goes dark, with the fifth: that is the whole plan now. The cracked hill behind the hall.**"}'::jsonb),
('dark-moon', 1, 6, 4, '{"place":"The hill behind the hall (Three nights)","narrated":false,"tone":"wry","cupNight":false,"opener":"That hill was steeper than it looked. Sit.","forkA":"The rock waits for the dark moon.","forkB":"The rock will open for us now.","callback":"Upriver, a dog on a chain kept the hidden path. Today a soldier stood in the crack with its back to the hall.","nudge":"{friend:Craft}, nobody has walked that crack before us. Why keep a soldier at it?","riddle":{"q":"What changes shape but is never touched?","a":"the moon","quip":"It keeps its own hours.","accept":["moon","the moon"],"maxTries":3},"leads":[{"id":"6-4-1","place":"inside the crack, by lamplight","actions":[{"attr":"Agility","verb":"go in sideways, lamp first"},{"attr":"Aim","verb":"light the ground ahead and look"}],"clueTitle":"The untouched grit","clueText":"Past where the soldier stood, the grit on the crack''s floor lies smooth and untouched. Your boots are the first marks in it.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"6-4-2","place":"the soldier in the mouth of the crack","actions":[{"attr":"Might","verb":"drag the broken armour aside"},{"attr":"Craft","verb":"look at the rock it stood on"}],"clueTitle":"Two hollows","clueText":"The rock where it stood is worn into two shallow hollows, one for each foot. It stood on that one spot, facing out, for a very long time.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"6-4-3","place":"the blank rock at the dead end","actions":[{"attr":"Agility","verb":"squeeze on to the very end"},{"attr":"Charm","verb":"keep everyone quiet, and listen"}],"clueTitle":"Louder here","clueText":"Put your ear to the blank rock. When the heartbeat comes, it is louder here than anywhere else in the crack.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"Forgive us for leaving it at all.\"* Why would leaving a way in need forgiving?","weekQuestion":"What will the fifth do in his hall?","pull":"**What does a full moon struck dark mean? The moon-tower.**"}'::jsonb),
('dark-moon', 1, 6, 5, '{"place":"The moon-tower (Two nights)","narrated":false,"tone":"wry","cupNight":false,"opener":"Two nights. Eat while there''s something to eat.","forkA":"The Seekers chose the dark moon.","forkB":"The dark moon came by chance.","callback":"The Order''s board has counted down for generations. The sky-watchers'' wall, counted forward, lands on the same night.","nudge":"{friend:Intellect}, the sky-watchers'' record stops on one night. Why that night?","riddle":{"q":"What is taken every night and returned at dawn?","a":"sleep","quip":"Get some.","accept":["sleep"],"maxTries":3},"leads":[{"id":"6-5-1","place":"the sky-watchers'' wall, row by row","actions":[{"attr":"Intellect","verb":"measure the space between the moons"},{"attr":"Aim","verb":"follow one row all the way round"}],"clueTitle":"A finger''s width","clueText":"Lay a finger between any two moons, on any row. The space is the same every time, year on year, round the whole room.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"6-5-2","place":"the floor of the round room","actions":[{"attr":"Craft","verb":"gather up what lies on the floor"},{"attr":"Intellect","verb":"read the scratches by daylight"}],"clueTitle":"Sums begun again","clueText":"On the floor lie the sky-watchers'' slates, scratched with long sums. Many are crossed through and begun again.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."},{"id":"6-5-3","place":"where the rows stop","actions":[{"attr":"Might","verb":"climb the ledges to the last rows"},{"attr":"Craft","verb":"run a thumb along the last cuts"}],"clueTitle":"Cut in a hurry","clueText":"In the last rows before they stop, every moon is cut to the right depth, but the edges are rough, as if made in a hurry. Not one night is missing.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"Be there when it does.\"* Be there to do what?","weekQuestion":"What will the fifth do in his hall?","pull":"**You have the hour. One piece is left, and the Seekers'' way ends at a blank rock with this same moon beside it. Tomorrow is the last day.**"}'::jsonb),
('dark-moon', 1, 6, 6, '{"place":"The crack in the hill (One night)","narrated":false,"tone":"wry","cupNight":true,"opener":"Last night of the count. Eat what you like.","forkA":"We open the rock tomorrow night.","forkB":"The door is not ours to open tomorrow.","callback":"Six nights ago you had a hidden room. Tonight you have one stroke left.","nudge":"{friend:Intellect}, not one of the dead turned its head. What do they know that we don''t?","riddle":{"q":"What gets better when you share it and worse when you keep it?","a":"a story","quip":"Tell one.","accept":["a story","story"],"maxTries":3},"leads":[{"id":"6-6-1","place":"the street below the crack","actions":[{"attr":"Aim","verb":"watch the street from the crack''s mouth"},{"attr":"Intellect","verb":"count the ranks as they climb"}],"clueTitle":"Every helm to the hall","clueText":"From the crack''s mouth you can see the whole street climbing toward you. Every helm in it is turned to the hall, not one to the hill.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"6-6-2","place":"the foot of the blank rock","actions":[{"attr":"Craft","verb":"look at how the grit lies"},{"attr":"Agility","verb":"get down low with the lamp"}],"clueTitle":"The swept fan","clueText":"At the foot of the blank rock, the old grit on your side lies swept flat in a smooth quarter-circle. Its point is at the rock''s left edge.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"6-6-3","place":"the streets you crossed this morning","actions":[{"attr":"Aim","verb":"look back down the hill from the crack"},{"attr":"Agility","verb":"go back the long way, street by street"}],"clueTitle":"Every post empty","clueText":"The crossroads, the gate-tower, the street under the wall: every place where a soldier stood is empty now. Only the pale marks of their boots are left.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"Finish what we could not.\"* What did the Seekers leave unfinished?","weekQuestion":"What will the fifth do in his hall?","pull":"**Tomorrow night, when the moon goes dark: through the Seekers'' door, into his hall, with the fifth in your hands.**"}'::jsonb)
